{
  "recommendation": "The strongest currently documented sign-up bonus is the EcoCard.",
  "offer": {
    "bonus": "2,000 sustainability points, worth $20 when redeemed as a statement credit or Rho-Bank checking-account credit",
    "requirement": "Spend at least $5,000 in eligible purchases during the first month after opening",
    "offer_window": "August 1, 2025 through December 15, 2025",
    "eligibility": "New customers; account must remain open and in good standing when the bonus is awarded",
    "annual_fee": "$50",
    "other_terms": "Returns, chargebacks, disputed transactions, balance transfers, cash equivalents, and fees do not count toward the spending requirement"
  },
  "bottom_line": "If you can comfortably spend $5,000 in the first month and value sustainability rewards, the EcoCard is the best active sign-up-bonus offer I found. However, the $50 annual fee means the bonus alone does not offset the fee.",
  "other_documented_offers": [
    {
      "card": "Silver Rewards Card",
      "offer": "$500 statement credit after $2,000 in purchases during the first month",
      "status": "Expired; the documented offer window ended June 30, 2025"
    },
    {
      "card": "Silver Rewards Card",
      "offer": "0% introductory APR for the first year",
      "status": "Active through December 31, 2025, but this is not a points or cash-back sign-up bonus"
    },
    {
      "card": "Silver Zoom Card",
      "offer": "Triple cash back for nine months from account opening",
      "status": "Available through December 31, 2025; the documentation does not state a fixed sign-up-bonus amount and identifies it as a business-card offer"
    }
  ],
  "next_step": "If you tell me whether you want a personal or business card and how much you typically spend in the first month, I can help determine whether the EcoCard or another option is the better fit."
}
